388	      let cleanup: (() => void) | undefined;
389	      initTerminal().then((c) => { cleanup = c; });
390	
391	      return () => {
392	        if (cleanup) cleanup();
393	      };
394	    }
395	  }, [isOpen, nodeId, loadRealLogs, connectSSH]);
396	
