527	              />
528	            </div>
529	          ))}
530	        </div>
531	
532	        <div className="p-2 border-t border-blue-600/20 bg-slate-900/50 flex justify-between items-center px-4 shrink-0">
533	          <div className="flex items-center space-x-4">
534	            <div className="flex items-center text-[9px] text-slate-500 font-bold uppercase">
535	              <div className={`w-1.5 h-1.5 rounded-full mr-1.5 ${sshConnected ? 'bg-green-500' : 'bg-yellow-500'}`} />
536	              {activeTab === 'supervisor' ? `${connectionMode.toUpperCase()}: ${sshConnected ? 'ACTIVE' : 'LOCAL'}` : 'INNER AGENT: ACTIVE'}
537	            </div>
